# apply_hp_sweep_and_run.py — drops updated files and sweeps hyperparameter /
# feature-drop configs. Baseline (previous best) is matchup_ll = 0.6209.
import base64, sys, pathlib

FILES = {
    'src/models/gbm_ranker.py': '',
    'src/eval/backtest_gbm_walkforward.py': '',
}


def main():
    for target, b64 in FILES.items():
        p = pathlib.Path(target)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(b64))
        print(f"wrote {target}")

    import pandas as pd
    from src.eval.backtest_gbm_walkforward import backtest_gbm_walkforward, summarize_wf

    races = pd.read_parquet("data/processed/races.parquet").sort_values("date").reset_index(drop=True)
    entries = pd.read_parquet("data/processed/entries.parquet")
    sessions = pd.read_parquet("data/processed/sessions.parquet")
    loopstats = pd.read_parquet("data/processed/loopstats.parquet")

    ALPHA = 0.85
    configs = [
        ("baseline (previous best)", None, {}),
        ("no-driver",                ["driver"], {}),
        ("tight-reg",                None, {"num_leaves": 31, "min_data_in_leaf": 25, "lambda_l2": 2.0}),
        ("no-driver + tight",        ["driver"], {"num_leaves": 31, "min_data_in_leaf": 25, "lambda_l2": 2.0}),
        ("very-tight",               None, {"num_leaves": 15, "min_data_in_leaf": 40, "lambda_l2": 5.0, "learning_rate": 0.03, "num_boost_round": 800}),
        ("no-driver + no-team",      ["driver", "team"], {}),
    ]

    results = {}
    for name, drop, kw in configs:
        print(f"\n--- {name} ---")
        out = backtest_gbm_walkforward(
            races, entries, sessions, loopstats,
            initial_train_races=36, retrain_every_n=10,
            calib_window=25, recalibrate_every_n=10,
            ensemble_alpha=ALPHA, n_samples=3000,
            drop_features=drop, gbm_fit_kwargs=kw,
        )
        s = summarize_wf(out["metrics"]).loc["ALL"]
        results[name] = s
        print(f"  matchup_ll={s['matchup_logloss']:.4f}  winner_ll={s['winner_logloss']:.4f}  "
              f"spearman={s['spearman_rho']:.4f}  top5={s['top5_accuracy']:.4f}")

    print("\n=== SUMMARY (alpha=0.85, walk-forward) ===")
    df = pd.DataFrame({k: v[["winner_logloss","matchup_logloss","spearman_rho","top5_accuracy"]]
                       for k, v in results.items()}).T
    df.index.name = "config"
    print(df.round(4).to_string())

    best = df["matchup_logloss"].idxmin()
    print(f"\nBest config: {best} (matchup_ll = {df.loc[best, 'matchup_logloss']:.4f})")

if __name__ == "__main__":
    main()
